const CACHE='campus-schedule-shell-v11';
const SHELL=['./','./index.html','./styles.css?v=11','./app.js?v=2','./core.js?v=11','./importers.js?v=4','./sample.json','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(async cache=>{for(const path of SHELL){const response=await fetch(path);if(response.ok&&!response.redirected)await cache.put(path,response);}}).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('campus-schedule-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin)return;if(!SHELL.some(path=>new URL(path,self.location.href).pathname===url.pathname)&&!url.pathname.includes('/vendor/'))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);if(request.mode==='navigate'){try{const response=await fetch(request);if(response.ok&&!response.redirected)await cache.put(request,response.clone());return response;}catch{return (await cache.match(request))||(await cache.match('./index.html'))||Response.error();}}const saved=await cache.match(request);if(saved)return saved;const response=await fetch(request);if(response.ok&&!response.redirected)await cache.put(request,response.clone());return response;})());});
